use std::future::Future;
use std::sync::Arc;

use crate::error::DiscordError;
use crate::model::{ChannelId, GuildId, Member, Message, MessageId, Presence, UserId};

use super::CacheHandle;

/// Identity of one clear operation, generated by the client that issues it.
///
/// A clear can commit in the store while its response is lost. The client
/// then retries the same clear with the same id and the same expected epoch;
/// the store recognizes its own last applied clear by this id and answers
/// `Applied` again instead of `Rejected`, so the sole writer is not mistaken
/// for a superseded one. `client` should be unique per client instance (the
/// gateway runtime uses a random value) and `sequence` unique per clear.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct CacheClearId {
    /// Identifies the issuing client.
    pub client: u64,
    /// Identifies the clear within that client.
    pub sequence: u64,
}

/// Result of a conditional clear: see the [`CacheBackend`] epoch contract.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CacheClear {
    /// The store's epoch matched the expected one; the entries were cleared
    /// and the store's epoch is now this (incremented) value.
    Applied(u64),
    /// The store's epoch did not match — another client cleared the store
    /// since this caller last observed it. Nothing was changed; carries the
    /// store's current epoch.
    Rejected(u64),
}

/// Async extension point for external cache stores.
///
/// The trait focuses on the TTL-backed hot path first: members, messages, and
/// presences. Implementors can back these calls with Redis, DragonflyDB,
/// Valkey, or another shared store while preserving the `Arc`-returning read
/// shape used by the in-memory cache.
///
/// # Epoch contract (normative)
///
/// 1. The store keeps **one** epoch for all of its entries, starting at 0.
/// 2. [`clear_cache`](Self::clear_cache) and
///    [`clear_shard_cache`](Self::clear_shard_cache) are conditional: if the
///    store's epoch equals `expected_epoch`, delete the entries in scope,
///    increment the epoch, record `clear_id` together with the new epoch as
///    the last applied clear, and return [`CacheClear::Applied`] with the new
///    epoch.
/// 3. Otherwise, if `clear_id` equals the id of the last applied clear, the
///    call is a retry of a clear that already committed (its response was
///    lost): change nothing and return [`CacheClear::Applied`] with the epoch
///    that clear produced. In every other case change nothing and return
///    [`CacheClear::Rejected`] with the current epoch. Compare, delete,
///    increment, and recording the id must be atomic (for example one Lua
///    script or `MULTI`/`EXEC` transaction in Redis).
/// 4. Every write (`put_*`, `delete_*`) carries the epoch it was issued
///    under. If that epoch is lower than the store's current epoch the write
///    must be ignored and reported as `Ok(())`; the comparison and the write
///    must be atomic with respect to a concurrent clear.
/// 5. Any clear — full or per shard — therefore invalidates every earlier
///    epoch, so a shard-count change (which the gateway runtime always
///    starts with a full clear) leaves no old-layout writer able to insert
///    or delete data.
///
/// # One writer per store — enforce it yourself
///
/// Only one running client may write to a store (or key namespace). This is
/// **not** detected when a client starts: a client's first clear adopts the
/// store's current epoch and claims the store, so a second client that
/// starts while the first is running takes the store over without either
/// noticing. Both then report healthy, but the first client's writes are
/// silently ignored (their epoch is too old) until its next clear — a shard
/// reconnecting or a recovery — is rejected; from then on it reports
/// `superseded` in its health, stops mirroring, and its shutdown returns an
/// error. Deploy so that a store is never shared: one store or namespace
/// per process, and stop the old process before starting its replacement
/// (an old client's delayed writes and clears are rejected either way).
/// [`CacheHandle`] implements this contract for the in-memory store.
///
/// # Implementing and the `Send` contract
///
/// Implement the methods as plain `async fn`; no attribute macro is needed.
/// They are declared as `fn ... -> impl Future<Output = ...> + Send` because
/// the gateway runtime calls the backend from a spawned Tokio task, so each
/// `async fn` must produce a `Send` future (no `Rc`, `RefCell` borrow, or
/// `std::sync::MutexGuard` held across an `.await`); a violation is a
/// compile error at the impl. The trait is not object safe: register a
/// backend with `ClientBuilder::cache_backend(Arc::new(backend))`, which
/// stores it type-erased.
pub trait CacheBackend: Send + Sync {
    /// Conditionally clears every entry; see the epoch contract.
    fn clear_cache(
        &self,
        expected_epoch: u64,
        clear_id: CacheClearId,
    ) -> impl Future<Output = Result<CacheClear, DiscordError>> + Send;

    /// Conditionally clears the entries owned by gateway shard `shard_id`
    /// of `shard_count`; see the epoch contract.
    ///
    /// The gateway runtime calls this when that shard starts a new session
    /// (READY), when the shard stops after losing events, and to resync the
    /// shard after a write was dropped or failed, so the mirror is never
    /// left stale.
    ///
    /// Ownership follows [`CacheHandle::clear_shard`]: a guild belongs to
    /// shard `(guild_id >> 22) % shard_count`, DMs belong to shard 0, and
    /// users are global. With `shard_count <= 1` every entry belongs to the
    /// shard. Implementations must delete the members, presences, and
    /// messages of the shard's guilds (and DM messages on shard 0); there is
    /// deliberately no default, because silently keeping entries would make
    /// the mirror stale.
    fn clear_shard_cache(
        &self,
        expected_epoch: u64,
        clear_id: CacheClearId,
        shard_id: u32,
        shard_count: u32,
    ) -> impl Future<Output = Result<CacheClear, DiscordError>> + Send;

    fn purge_expired_entries(&self) -> impl Future<Output = Result<(), DiscordError>> + Send;

    /// Stores a member unless `epoch` is older than the store's epoch.
    fn put_member(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
        member: Member,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;

    fn get_member(
        &self,
        guild_id: GuildId,
        user_id: UserId,
    ) -> impl Future<Output = Result<Option<Arc<Member>>, DiscordError>> + Send;

    fn list_members(
        &self,
        guild_id: GuildId,
    ) -> impl Future<Output = Result<Vec<Arc<Member>>, DiscordError>> + Send;

    /// Deletes a member unless `epoch` is older than the store's epoch.
    fn delete_member(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;

    /// Stores a message unless `epoch` is older than the store's epoch.
    fn put_message(
        &self,
        epoch: u64,
        message: Message,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;

    fn get_message(
        &self,
        channel_id: ChannelId,
        message_id: MessageId,
    ) -> impl Future<Output = Result<Option<Arc<Message>>, DiscordError>> + Send;

    fn list_messages(
        &self,
        channel_id: ChannelId,
    ) -> impl Future<Output = Result<Vec<Arc<Message>>, DiscordError>> + Send;

    /// Deletes a message unless `epoch` is older than the store's epoch.
    fn delete_message(
        &self,
        epoch: u64,
        channel_id: ChannelId,
        message_id: MessageId,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;

    /// Stores a presence unless `epoch` is older than the store's epoch.
    fn put_presence(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
        presence: Presence,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;

    fn get_presence(
        &self,
        guild_id: GuildId,
        user_id: UserId,
    ) -> impl Future<Output = Result<Option<Arc<Presence>>, DiscordError>> + Send;

    fn list_presences(
        &self,
        guild_id: GuildId,
    ) -> impl Future<Output = Result<Vec<Arc<Presence>>, DiscordError>> + Send;

    /// Deletes a presence unless `epoch` is older than the store's epoch.
    fn delete_presence(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
    ) -> impl Future<Output = Result<(), DiscordError>> + Send;
}

impl CacheBackend for CacheHandle {
    async fn clear_cache(
        &self,
        expected_epoch: u64,
        clear_id: CacheClearId,
    ) -> Result<CacheClear, DiscordError> {
        Ok(self.clear_if_epoch(expected_epoch, clear_id, None).await)
    }

    async fn clear_shard_cache(
        &self,
        expected_epoch: u64,
        clear_id: CacheClearId,
        shard_id: u32,
        shard_count: u32,
    ) -> Result<CacheClear, DiscordError> {
        Ok(self
            .clear_if_epoch(expected_epoch, clear_id, Some((shard_id, shard_count)))
            .await)
    }

    async fn purge_expired_entries(&self) -> Result<(), DiscordError> {
        self.purge_expired().await;
        Ok(())
    }

    async fn put_member(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
        member: Member,
    ) -> Result<(), DiscordError> {
        self.fenced_upsert_member(epoch, guild_id, user_id, Arc::new(member))
            .await;
        Ok(())
    }

    async fn get_member(
        &self,
        guild_id: GuildId,
        user_id: UserId,
    ) -> Result<Option<Arc<Member>>, DiscordError> {
        Ok(self.member_arc(guild_id, user_id).await)
    }

    async fn list_members(&self, guild_id: GuildId) -> Result<Vec<Arc<Member>>, DiscordError> {
        Ok(self.members_arc(guild_id).await)
    }

    async fn delete_member(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
    ) -> Result<(), DiscordError> {
        self.fenced_remove_member(epoch, guild_id, user_id).await;
        Ok(())
    }

    async fn put_message(&self, epoch: u64, message: Message) -> Result<(), DiscordError> {
        self.fenced_upsert_message(epoch, Arc::new(message)).await;
        Ok(())
    }

    async fn get_message(
        &self,
        channel_id: ChannelId,
        message_id: MessageId,
    ) -> Result<Option<Arc<Message>>, DiscordError> {
        Ok(self.message_arc(channel_id, message_id).await)
    }

    async fn list_messages(
        &self,
        channel_id: ChannelId,
    ) -> Result<Vec<Arc<Message>>, DiscordError> {
        Ok(self.messages_arc(channel_id).await)
    }

    async fn delete_message(
        &self,
        epoch: u64,
        channel_id: ChannelId,
        message_id: MessageId,
    ) -> Result<(), DiscordError> {
        self.fenced_remove_message(epoch, channel_id, message_id)
            .await;
        Ok(())
    }

    async fn put_presence(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
        presence: Presence,
    ) -> Result<(), DiscordError> {
        self.fenced_upsert_presence(epoch, guild_id, user_id, Arc::new(presence))
            .await;
        Ok(())
    }

    async fn get_presence(
        &self,
        guild_id: GuildId,
        user_id: UserId,
    ) -> Result<Option<Arc<Presence>>, DiscordError> {
        Ok(self.presence_arc(guild_id, user_id).await)
    }

    async fn list_presences(&self, guild_id: GuildId) -> Result<Vec<Arc<Presence>>, DiscordError> {
        Ok(self.presences_arc(guild_id).await)
    }

    async fn delete_presence(
        &self,
        epoch: u64,
        guild_id: GuildId,
        user_id: UserId,
    ) -> Result<(), DiscordError> {
        self.fenced_remove_presence(epoch, guild_id, user_id).await;
        Ok(())
    }
}
